package build

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"slices"
	"sort"
	"strings"
	"time"
)

// Epoch is the fixed modification time §8.2 requires for an entry with no
// source: a file generated by §6.8, or given directly by a [[file]] entry.
// Exported for Repack's callers, which must supply it for the same reason.
var Epoch = time.Date(1980, 1, 1, 0, 0, 0, 0, time.UTC)

// RawSource is an entry's original, already-compressed form in a zip
// archive, letting Repack's caller (internal/repack) defer decompressing
// an entry until something in the pipeline actually needs its content.
type RawSource struct {
	Method           uint16 // zip.Store or zip.Deflate
	CRC32            uint32
	CompressedSize   uint64
	UncompressedSize uint64
	Decompressed     func() ([]byte, error)        // the entry's full, decompressed content
	Open             func() (io.ReadCloser, error) // streams the decompressed content; optional
	Raw              func() (io.Reader, error)     // the entry's still-compressed bytes, for pass-through
}

// fileEntry is one file in the build, backed by disk, by in-memory content,
// or by a RawSource, with the modification time §8.2 requires its archive
// entry to carry.
type fileEntry struct {
	diskPath string // absolute path to the backing file; "" if data/source is set
	ranged   bool   // the content is diskLen bytes of diskPath from diskOff
	diskOff  int64
	diskLen  int64
	data     []byte     // in-memory content; authoritative when non-nil
	source   *RawSource // original compressed form; set only until data is filled
	modified time.Time
}

func diskEntry(path string, modified time.Time) *fileEntry {
	return &fileEntry{diskPath: path, modified: modified}
}

// rangeEntry is n bytes of the file at path from off: a file extracted
// from a disc image, left in place rather than read into memory.
func rangeEntry(path string, off, n int64, modified time.Time) *fileEntry {
	return &fileEntry{diskPath: path, ranged: true, diskOff: off, diskLen: n, modified: modified}
}

func dataEntry(data []byte, modified time.Time) *fileEntry {
	return &fileEntry{data: data, modified: modified}
}

func sourceEntry(source *RawSource, modified time.Time) *fileEntry {
	return &fileEntry{source: source, modified: modified}
}

// bytes returns the entry's content, decompressing (and caching) a
// RawSource-backed entry if necessary.
func (e *fileEntry) bytes() ([]byte, error) {
	if e.data != nil {
		return e.data, nil
	}
	if e.source != nil {
		data, err := e.source.Decompressed()
		if err != nil {
			return nil, err
		}
		e.data = data
		return data, nil
	}
	if e.ranged {
		rc, err := e.openRange(0, e.diskLen)
		if err != nil {
			return nil, err
		}
		defer rc.Close()
		return io.ReadAll(rc)
	}
	return os.ReadFile(e.diskPath)
}

// peek returns the entry's content like bytes, but without caching a
// RawSource-backed entry's decompressed content: for reading an entry
// only to inspect it, which shouldn't keep it in memory or stop
// writeArchive from passing it through raw.
func (e *fileEntry) peek() ([]byte, error) {
	if e.data == nil && e.source != nil {
		return e.source.Decompressed()
	}
	return e.bytes()
}

// open streams the entry's content, avoiding a copy for disk-backed entries.
// A RawSource-backed entry is fully decompressed here too: open is only
// used once writeArchive has already decided not to pass the entry's raw
// compressed bytes straight through (see rawPassthrough).
func (e *fileEntry) open() (*os.File, []byte, error) {
	if e.data != nil {
		return nil, e.data, nil
	}
	if e.source != nil {
		data, err := e.bytes()
		return nil, data, err
	}
	f, err := os.Open(e.diskPath)
	return f, nil, err
}

// reader returns the entry's content as a stream: a file on disk (seekable,
// so zipw can store it without a copy), its bytes, or an archive entry
// decompressed on the fly rather than read into memory. The caller closes
// it if it is an io.Closer.
func (e *fileEntry) reader() (io.Reader, error) {
	if e.data == nil && e.source != nil && e.source.Open != nil {
		return e.source.Open()
	}
	if e.data == nil && e.ranged {
		f, err := os.Open(e.diskPath)
		if err != nil {
			return nil, err
		}
		return &sectionFile{io.NewSectionReader(f, e.diskOff, e.diskLen), f}, nil
	}
	f, data, err := e.open()
	if err != nil {
		return nil, err
	}
	if f != nil {
		return f, nil
	}
	return bytes.NewReader(data), nil
}

// size returns the entry's uncompressed size without reading its content.
func (e *fileEntry) size() (int64, error) {
	if e.data != nil {
		return int64(len(e.data)), nil
	}
	if e.source != nil {
		return int64(e.source.UncompressedSize), nil
	}
	if e.ranged {
		return e.diskLen, nil
	}
	info, err := os.Stat(e.diskPath)
	if err != nil {
		return 0, err
	}
	return info.Size(), nil
}

// openRange streams n bytes of the entry's content starting at off,
// without loading the whole entry into memory: §6.4 reads disc images
// that can be hundreds of megabytes. A RawSource-backed entry without
// Open, or one already read into memory, is served from its bytes.
func (e *fileEntry) openRange(off, n int64) (io.ReadCloser, error) {
	if e.data == nil && e.source != nil && e.source.Open != nil {
		rc, err := e.source.Open()
		if err != nil {
			return nil, err
		}
		if _, err := io.CopyN(io.Discard, rc, off); err != nil {
			rc.Close()
			return nil, err
		}
		return readCloser{io.LimitReader(rc, n), rc}, nil
	}
	if e.data == nil && e.source == nil {
		f, err := os.Open(e.diskPath)
		if err != nil {
			return nil, err
		}
		if e.ranged {
			off, n = e.diskOff+min(off, e.diskLen), min(n, max(e.diskLen-off, 0))
		}
		return readCloser{io.NewSectionReader(f, off, n), f}, nil
	}
	data, err := e.bytes()
	if err != nil {
		return nil, err
	}
	return io.NopCloser(bytes.NewReader(data[min(off, int64(len(data))):min(off+n, int64(len(data)))])), nil
}

type readCloser struct {
	io.Reader
	io.Closer
}

// sectionFile is part of an open file: seekable, so zipw can store it
// without spooling, and closable.
type sectionFile struct {
	sr *io.SectionReader
	f  *os.File
}

func (s *sectionFile) Read(p []byte) (int, error)                { return s.sr.Read(p) }
func (s *sectionFile) Seek(off int64, whence int) (int64, error) { return s.sr.Seek(off, whence) }
func (s *sectionFile) Close() error                              { return s.f.Close() }

// rawPassthrough returns the entry's RawSource if nothing has read or
// replaced its content since it was collected, so writeArchive can copy its
// already-compressed bytes through unchanged instead of decompressing and
// recompressing them.
func (e *fileEntry) rawPassthrough() *RawSource {
	if e.data != nil {
		return nil
	}
	return e.source
}

// fileSet is the build in progress. Paths match case-insensitively (§2),
// keeping the most recently set casing.
type fileSet struct {
	files map[string]*fileEntry // canonical-case path -> entry
	index map[string]string     // lower-case path -> canonical-case path
}

func newFileSet() *fileSet {
	return &fileSet{files: map[string]*fileEntry{}, index: map[string]string{}}
}

// set adds or replaces path case-insensitively, adopting path's casing.
func (fs *fileSet) set(path string, e *fileEntry) {
	lower := strings.ToLower(path)
	if existing, ok := fs.index[lower]; ok && existing != path {
		delete(fs.files, existing)
	}
	fs.files[path] = e
	fs.index[lower] = path
}

func (fs *fileSet) delete(path string) {
	lower := strings.ToLower(path)
	if existing, ok := fs.index[lower]; ok {
		delete(fs.files, existing)
		delete(fs.index, lower)
	}
}

func (fs *fileSet) get(path string) (*fileEntry, bool) {
	existing, ok := fs.index[strings.ToLower(path)]
	if !ok {
		return nil, false
	}
	return fs.files[existing], true
}

// paths returns every path, sorted by UTF-8 byte order (§8.2).
func (fs *fileSet) paths() []string {
	out := make([]string, 0, len(fs.files))
	for p := range fs.files {
		out = append(out, p)
	}
	sort.Strings(out) // already byte-wise over UTF-8
	return out
}

// dirNode is a directory in the tree flatten builds from a fileSet.
type dirNode struct {
	files map[string]*fileEntry
	dirs  map[string]*dirNode
}

func newDirNode() *dirNode {
	return &dirNode{files: map[string]*fileEntry{}, dirs: map[string]*dirNode{}}
}

func buildTree(fs *fileSet) *dirNode {
	root := newDirNode()
	for p, e := range fs.files {
		parts := strings.Split(p, "/")
		cur := root
		for i, part := range parts {
			if i == len(parts)-1 {
				cur.files[part] = e
				continue
			}
			child, ok := cur.dirs[part]
			if !ok {
				child = newDirNode()
				cur.dirs[part] = child
			}
			cur = child
		}
	}
	return root
}

// flattenNode collapses single-subdirectory-only directories bottom-up
// (§6.3), recording each collapsed name into dropped, in path order, and
// each collision a collapse would cause into errs. prefix is n's path.
func flattenNode(n *dirNode, prefix string, dropped *[]string, errs *[]error) {
	for _, name := range sortedKeys(n.dirs) {
		flattenNode(n.dirs[name], path.Join(prefix, name), dropped, errs)
	}
	n.dirs = collapseChildren(n, prefix, dropped, errs)
}

// collapseChildren walks each of n's subdirectories' chain of
// single-subdirectory-only directories down to where it bottoms out, and
// keeps that node instead. A collapsed directory whose new name matches
// another of n's entries case-insensitively is a collision (§6.3, §11):
// one would replace the other.
func collapseChildren(n *dirNode, prefix string, dropped *[]string, errs *[]error) map[string]*dirNode {
	type kept struct {
		from, to  string // the entry's name before and after collapsing
		collapsed bool
	}
	byLower := map[string][]kept{} // lower-case new name -> entries taking it
	for name := range n.files {
		byLower[strings.ToLower(name)] = append(byLower[strings.ToLower(name)], kept{from: name, to: name})
	}
	result := make(map[string]*dirNode, len(n.dirs))
	for _, name := range sortedKeys(n.dirs) {
		curName, curNode := name, n.dirs[name]
		for len(curNode.files) == 0 && len(curNode.dirs) == 1 {
			*dropped = append(*dropped, curName)
			for subName, subNode := range curNode.dirs {
				curName, curNode = subName, subNode
			}
		}
		lower := strings.ToLower(curName)
		byLower[lower] = append(byLower[lower], kept{from: name, to: curName, collapsed: curName != name})
		result[curName] = curNode
	}
	for _, lower := range sortedKeys(byLower) {
		ks := byLower[lower]
		// Case variants already in the build (neither collapsed) are left
		// as they were; only a collapse can cause a collision.
		if len(ks) < 2 || !slices.ContainsFunc(ks, func(k kept) bool { return k.collapsed }) {
			continue
		}
		var from []string
		for _, k := range ks {
			from = append(from, path.Join(prefix, k.from))
		}
		*errs = append(*errs, fmt.Errorf("layout.flatten: %s would collide at %s (§6.3)", strings.Join(from, " and "), path.Join(prefix, ks[0].to)))
	}
	return result
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func collectPaths(n *dirNode, prefix string, out *fileSet) {
	for name, e := range n.files {
		out.set(path.Join(prefix, name), e)
	}
	for name, child := range n.dirs {
		collectPaths(child, path.Join(prefix, name), out)
	}
}

// flatten applies §6.3 to fs in place, returning changed paths (old -> new)
// and the directory names collapsed away. A collision leaves fs unchanged
// and returns an error naming every one.
func flatten(fs *fileSet, enabled bool) (moved map[string]string, dropped []string, err error) {
	if !enabled {
		return nil, nil, nil
	}

	byEntry := make(map[*fileEntry]string, len(fs.files))
	for p, e := range fs.files {
		byEntry[e] = p
	}

	root := buildTree(fs)
	var errs []error
	flattenNode(root, "", &dropped, &errs)
	if len(errs) > 0 {
		return nil, nil, errors.Join(errs...)
	}

	newFS := newFileSet()
	collectPaths(root, "", newFS)

	moved = map[string]string{}
	for p, e := range newFS.files {
		if old, ok := byEntry[e]; ok && old != p {
			moved[old] = p
		}
	}

	fs.files = newFS.files
	fs.index = newFS.index
	return moved, dropped, nil
}
